mapper.select:
SELECT * FROM goal
WHERE user_id = #{userId}
ORDER BY enabled DESC, created_at ASC

SELECT * FROM goal
WHERE user_id = #{userId}
  AND goal_type = #{goalType}
  AND enabled = 1
ORDER BY created_at DESC, id DESC
LIMIT 1

SELECT * FROM goal
WHERE user_id = #{userId}
  AND goal_type = #{goalType}
  AND target_value = #{targetValue}
  AND period = #{period}
LIMIT 1
